long startTime = System.nanoTime();
try {
    chain.doFilter(request, response);
} finally {
    long duration = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startTime);
    if (duration > 500) {
        logger.warn("Slow API detected: {} took {}ms", request.getRequestURI(), duration);
